PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?source (COUNT(?cashFlowId) AS ?transactionCount) (SUM(xsd:decimal(?amount)) AS ?totalAmount)
WHERE {
  ?cf rdf:type wm:CashFlow .
  OPTIONAL { ?cf wm:source ?source . }
  OPTIONAL { ?cf wm:cashFlowId ?cashFlowId . }
  OPTIONAL { ?cf wm:amount ?amount . }
}
GROUP BY ?source

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance ?goalCountBucket (COUNT(DISTINCT ?investor) AS ?investorCount)
WHERE {
  {
    SELECT ?investor ?riskTolerance (COUNT(DISTINCT ?goal) AS ?goalCount)
    WHERE {
      ?investor rdf:type wm:Investor .
      OPTIONAL { ?investor wm:riskTolerance ?riskTolerance . }
      OPTIONAL { ?investor wm:hasInvestmentGoal ?goal . }
    }
    GROUP BY ?investor ?riskTolerance
  }
  FILTER(?goalCount > 0)
  BIND(
    IF(?goalCount = 1, "1",
      IF(?goalCount = 2, "2",
        IF(?goalCount = 3, "3", "4+")
      )
    ) AS ?goalCountBucket
  )
}
GROUP BY ?riskTolerance ?goalCountBucket
ORDER BY ?riskTolerance ?goalCountBucket

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?sectorLabel ?sector ?totalHoldingValue ?totalSectorAllocation WHERE {
  {
    SELECT ?sector (SUM(xsd:decimal(?val)) AS ?totalHoldingValue) WHERE {
      ?holding rdf:type wm:PortfolioHolding .
      ?holding wm:currentValue ?val .
      ?holding wm:sector ?sector .
    }
    GROUP BY ?sector
  }
  OPTIONAL {
    SELECT ?sector (SUM(xsd:decimal(?inv)) AS ?totalSectorAllocation) WHERE {
      ?alloc rdf:type wm:SectorAllocation .
      ?alloc wm:totalInvestment ?inv .
      ?alloc wm:sector ?sector .
    }
    GROUP BY ?sector
  }
  OPTIONAL { ?sector rdfs:label ?sectorLabel . }
}
ORDER BY ?sectorLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?investor rdf:type wm:Investor ;
            wm:investorId ?investorId .
  OPTIONAL { ?investor wm:investorName ?investorName . }

  ?cashflow rdf:type wm:CashFlow ;
            wm:cashFlowOfInvestor ?investor ;
            wm:date ?cdate .
  FILTER(CONTAINS(LCASE(STR(?cdate)), "2025"))

  FILTER NOT EXISTS {
    ?holding rdf:type wm:PortfolioHolding ;
             wm:heldByInvestor ?investor ;
             wm:purchaseDate ?hdate .
    FILTER(CONTAINS(LCASE(STR(?hdate)), "2025"))
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskScore 
       (SUM(xsd:decimal(?holdingValue)) AS ?totalHoldingValue) 
       (SUM(xsd:decimal(?sectorInvestment)) AS ?totalSectorAllocationInvestment)
WHERE {
  ?investor rdf:type wm:Investor .
  ?ph rdf:type wm:PortfolioHealth ;
      wm:healthOfInvestor ?investor ;
      wm:riskScore ?riskScore .

  OPTIONAL {
    ?holding rdf:type wm:PortfolioHolding ;
             wm:heldByInvestor ?investor ;
             wm:currentValue ?holdingValue .
  }

  OPTIONAL {
    ?sa rdf:type wm:SectorAllocation ;
        wm:allocationOfInvestor ?investor ;
        wm:totalInvestment ?sectorInvestment .
  }
}
GROUP BY ?riskScore

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName WHERE {
  {
    SELECT ?investor (AVG(xsd:decimal(?prog)) AS ?avgProg) WHERE {
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:belongsToInvestor ?investor .
      ?goal wm:progressPct ?prog .
    } GROUP BY ?investor
    HAVING (AVG(xsd:decimal(?prog)) < 30)
  }

  ?investor rdf:type wm:Investor .
  OPTIONAL { ?investor wm:investorId ?investorId . }
  OPTIONAL { ?investor wm:investorName ?investorName . }

  ?ph rdf:type wm:PortfolioHealth .
  ?ph wm:healthOfInvestor ?investor .
  ?ph wm:riskScore ?riskScore .
  FILTER(xsd:decimal(?riskScore) > 60)

  FILTER EXISTS {
    ?sa rdf:type wm:SectorAllocation .
    ?sa wm:allocationOfInvestor ?investor .
    ?sa wm:allocationPct ?allocPct .
    FILTER(xsd:decimal(?allocPct) > 30)
  }
}

