}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?categoryLabel ?sectorLabel (COUNT(?holding) AS ?holdingCount)
WHERE {
  ?investor rdf:type wm:Investor .
  OPTIONAL {
    ?investor wm:hasCategory ?cat .
    ?cat rdf:type wm:Category .
    OPTIONAL { ?cat rdfs:label ?catLabel . }
    OPTIONAL { ?cat wm:category ?catLiteral . BIND(?catLiteral AS ?catLabel) }
  }
  BIND(COALESCE(?catLabel, "NULL") AS ?categoryLabel) .

  ?holding rdf:type wm:PortfolioHolding .
  ?holding wm:heldByInvestor ?investor .

  OPTIONAL {
    ?holding wm:hasSector ?sec .
    ?sec rdf:type wm:Sector .
    OPTIONAL { ?sec rdfs:label ?secLabel . }
    OPTIONAL { ?holding wm:sector ?secLiteral . BIND(?secLiteral AS ?secLabel) }
  }
  BIND(COALESCE(?secLabel, "NULL") AS ?sectorLabel) .
}
GROUP BY ?categoryLabel ?sectorLabel

