PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?score
WHERE {
  # Investor basic info
  ?inv rdf:type wm:Investor .
  ?inv wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }

  # Shortfall aggregation
  {
    SELECT ?investorId (SUM(xsd:decimal(?shortfall)) AS ?totalShortfall)
    WHERE {
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:investorId ?investorId .
      ?goal wm:shortfall ?shortfall .
    }
    GROUP BY ?investorId
  }

  # Holding gain aggregation
  {
    SELECT ?investorId (SUM(xsd:decimal(?gain)) AS ?totalHoldingGain)
    WHERE {
      ?holding rdf:type wm:PortfolioHolding .
      ?holding wm:investorId ?investorId .
      ?holding wm:currentValue ?currentValue .
      ?holding wm:cost ?cost .
      BIND((xsd:decimal(?currentValue) - xsd:decimal(?cost)) AS ?gain)
    }
    GROUP BY ?investorId
  }

  # Net cash flow aggregation
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?netCashFlow)
    WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:investorId ?investorId .
      ?cf wm:amount ?amount .
    }
    GROUP BY ?investorId
  }

  # Risk score
  {
    SELECT ?investorId (MAX(xsd:decimal(?riskScore)) AS ?riskScore)
    WHERE {
      ?ph rdf:type wm:PortfolioHealth .
      ?ph wm:investorId ?investorId .
      ?ph wm:riskScore ?riskScore .
    }
    GROUP BY ?investorId
  }

  # Compute quantitative burden score
  BIND( (?totalShortfall - ?totalHoldingGain - ?netCashFlow + ?riskScore) AS ?score )
}
ORDER BY DESC(?score)
LIMIT 10

