PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?temporalPressureScore
WHERE {
  # Investor basic info
  ?inv rdf:type wm:Investor .
  ?inv wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }

  # 2025 Net Cash Flow
  {
    SELECT ?investorId (SUM(xsd:decimal(?cfAmount)) AS ?cashFlow2025)
    WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:investorId ?investorId .
      ?cf wm:amount ?cfAmount .
      ?cf wm:date ?cfDate .
      FILTER(CONTAINS(?cfDate, "2025"))
    }
    GROUP BY ?investorId
  }

  # Rebalancing amount
  {
    SELECT ?investorId (SUM(xsd:decimal(?rebAmount)) AS ?rebalanceAmount)
    WHERE {
      ?ra rdf:type wm:RebalancingAction .
      ?ra wm:investorId ?investorId .
      ?ra wm:amount ?rebAmount .
    }
    GROUP BY ?investorId
  }

  # Goal shortfall
  {
    SELECT ?investorId (MAX(xsd:decimal(?shortfallVal)) AS ?shortfall)
    WHERE {
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:investorId ?investorId .
      ?goal wm:shortfall ?shortfallVal .
    }
    GROUP BY ?investorId
  }

  # Scenario allocation change
  {
    SELECT ?investorId (SUM(xsd:decimal(?allocChange)) AS ?allocChange)
    WHERE {
      ?sr rdf:type wm:ScenarioRebalancing .
      ?sr wm:investorId ?investorId .
      ?sr wm:newAllocationPct ?newAlloc .
      ?sr wm:currentAllocationPct ?curAlloc .
      BIND( (xsd:decimal(?newAlloc) - xsd:decimal(?curAlloc)) AS ?allocChange )
    }
    GROUP BY ?investorId
  }

  # Compute temporal pressure score
  BIND( (COALESCE(?cashFlow2025, 0) + COALESCE(?rebalanceAmount, 0) - COALESCE(?shortfall, 0) + COALESCE(?allocChange, 0)) AS ?temporalPressureScore )
}
ORDER BY DESC(?temporalPressureScore)
LIMIT 10

