PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?catLabel 
       (SUM(xsd:decimal(?totalCF)) AS ?totalCashFlow) 
       (SUM(?scenarioCount) AS ?totalScenarioChanges) 
       (AVG(?avgAllocPct) AS ?avgAllocationPct) 
       (SUM(xsd:decimal(?totalHolding)) AS ?totalSectorInvestment)
WHERE {
  ?investor rdf:type wm:Investor .

  OPTIONAL { 
    ?investor wm:hasCategory ?cat .
    ?cat rdfs:label ?categoryLabel .
  }
  BIND(COALESCE(?categoryLabel, "NULL") AS ?catLabel)

  OPTIONAL {
    {
      SELECT ?investor (SUM(xsd:decimal(?amount)) AS ?totalCF)
      WHERE {
        ?cf rdf:type wm:CashFlow .
        ?cf wm:cashFlowOfInvestor ?investor .
        ?cf wm:amount ?amount .
      }
      GROUP BY ?investor
    }
  }

  OPTIONAL {
    {
      SELECT ?investor (COUNT(?sr) AS ?scenarioCount)
      WHERE {
        ?sr rdf:type wm:ScenarioRebalancing .
        ?sr wm:scenarioRebalancingOfInvestor ?investor .
      }
      GROUP BY ?investor
    }
  }

  OPTIONAL {
    {
      SELECT ?investor (AVG(xsd:decimal(?allocPct)) AS ?avgAllocPct)
      WHERE {
        ?alloc rdf:type wm:SectorAllocation .
        ?alloc wm:allocationOfInvestor ?investor .
        ?alloc wm:allocationPct ?allocPct .
      }
      GROUP BY ?investor
    }
  }

  OPTIONAL {
    {
      SELECT ?investor (SUM(xsd:decimal(?value)) AS ?totalHolding)
      WHERE {
        ?ph rdf:type wm:PortfolioHolding .
        ?ph wm:heldByInvestor ?investor .
        ?ph wm:currentValue ?value .
      }
      GROUP BY ?investor
    }
  }
}
GROUP BY ?catLabel

