  FILTER ( xsd:decimal(?avgGoalProgress) < 25 )
  FILTER ( xsd:decimal(?riskScore) > 70 )
  FILTER ( xsd:decimal(?maxScenarioChange) > 20 )
}
ORDER BY DESC(?totalCashFlow)

